<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useSimnowMonitor } from '@/composables/useSimnowMonitor'
import type { MonitorKind, MonitorQuery } from '@/api/simnowMonitor'
import type { ProductOption } from '@/utils/productSearch'
import { curveGeometry, monitorMoney, monitorPercent, monitorReason, monitorTime, observerLabel } from '@/utils/simnowPresentation'

const props = defineProps<{ options: ProductOption[] }>()
function day(date: Date) { return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date) }
const end = new Date(), start = new Date(end); start.setDate(start.getDate() - 6)
const defaults: MonitorQuery = { kind: 'all', product: '', status: '', startDay: day(start), endDay: day(end) }
function stored(): MonitorQuery {
  try { const q = JSON.parse(sessionStorage.getItem('guiyi.simnow.query.v1') ?? 'null'); if (q && ['all', 'signal', 'risk', 'order', 'fill'].includes(q.kind) && /^[a-zA-Z]{0,3}$/.test(q.product) && typeof q.status === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(q.startDay) && /^\d{4}-\d{2}-\d{2}$/.test(q.endDay)) return q } catch {}
  return { ...defaults }
}
const query = ref<MonitorQuery>(stored()), section = ref<'positions' | 'records' | 'issues'>('positions')
const filtersOpen = ref(false), curveField = ref<'equity' | 'net_profit'>('equity')
const monitor = useSimnowMonitor(query.value), data = monitor.data
const validRange = computed(() => query.value.startDay <= query.value.endDay && (Date.parse(query.value.endDay) - Date.parse(query.value.startDay)) / 86400000 <= 93)
const geometry = computed(() => curveGeometry(data.value?.curve ?? [], curveField.value))
const hasAccount = computed(() => Boolean(data.value?.account))
const observer = computed(() => observerLabel(data.value))
const categories: { value: MonitorKind; label: string }[] = [{ value: 'all', label: '全部记录' }, { value: 'signal', label: '信号' }, { value: 'risk', label: '风控' }, { value: 'order', label: '订单' }, { value: 'fill', label: '成交' }]
const kindLabel = (kind: string) => categories.find(k => k.value === kind)?.label ?? kind
const factLabels: Record<string, string> = { trading_day: '原生交易日', reason: '处理原因', bar_end: '信号Bar结束', observed_at: '首次可用时间', margin: '新增保证金', projected_margin: '预计总占用', margin_limit: '保证金上限', price: '价格', fee: '实际手续费', quantity: '手数', side: '方向', offset: '开平', accepted_at: '原生受理时间', reconciled: '账户对账', filled_at: '原生成交时间', recorded_at: '记录时间', native_precision_seconds: '原生时间精度（秒）' }
function factValue(key: string, value: string | null) {
  if (value === null) return '—'
  if (key === 'reason') return monitorReason[value] ?? '已记录处理原因，来源区可核对原始代码'
  if (key === 'side') return value === 'BUY' ? '买入' : '卖出'
  if (key === 'offset') return value === 'OPEN' ? '开仓' : '平仓'
  if (key === 'reconciled') return value === 'true' ? '已核对' : '待核对'
  if (key.endsWith('_at') || key === 'bar_end') return monitorTime(value)
  if (['price', 'fee', 'margin', 'projected_margin', 'margin_limit'].includes(key)) return monitorMoney(value)
  return value
}
const dialog = ref<HTMLDialogElement | null>(null)
let focusBefore: HTMLElement | null = null, mounted = false
async function open(id: string) { focusBefore = document.activeElement as HTMLElement | null; void monitor.openDetail(id); await nextTick(); if (dialog.value && !dialog.value.open) dialog.value.showModal() }
function close() { dialog.value?.close(); monitor.closeDetail(); void nextTick(() => focusBefore?.isConnected && focusBefore.focus()) }
function visibility() { monitor.setVisible(document.visibilityState === 'visible') }
function refresh() { void monitor.refresh() }
function reset() { query.value = { ...defaults } }
watch(query, value => { try { sessionStorage.setItem('guiyi.simnow.query.v1', JSON.stringify(value)) } catch {} monitor.setQueryValid(validRange.value); if (validRange.value) monitor.setQuery(value) }, { deep: true })
onMounted(() => { mounted = true; visibility(); monitor.start(); document.addEventListener('visibilitychange', visibility) })
onBeforeUnmount(() => { mounted = false; document.removeEventListener('visibilitychange', visibility); dialog.value?.close(); monitor.dispose() })
watch(monitor.selectedId, async id => { if (id && mounted) { await nextTick(); if (dialog.value && !dialog.value.open) dialog.value.showModal() } })
</script>

<template>
  <section class="simnow-home" aria-label="模拟交易监控">
    <header class="simnow-heading"><div><h1>模拟交易</h1><p>火天大有 · 60分钟 <span>账户监控与执行复盘</span></p></div><div class="simnow-heading-actions"><span class="simnow-refresh-note">页面可见时每5秒更新</span><button type="button" :disabled="monitor.loading.value" @click="refresh">{{ monitor.loading.value ? '读取中…' : '刷新' }}</button></div></header>
    <p v-if="monitor.error.value" class="simnow-notice simnow-notice--warning" role="alert">{{ monitor.error.value }}</p>
    <div v-if="!hasAccount" class="simnow-empty simnow-empty--initial">
      <span class="simnow-empty-symbol" aria-hidden="true">≋</span>
      <h2>{{ monitor.loading.value ? '正在读取监控记录' : data?.status === 'unavailable' ? '监控记录暂不可用' : '尚未接入模拟交易监控' }}</h2>
      <p>完成一次受控账户接入后，这里将展示原生权益、持仓和执行记录。</p><p>没有记录不代表账户空仓或收益为零。此页面只读取本地记录，不连接柜台或触发交易。</p>
    </div>
    <template v-else-if="data">
      <div class="simnow-status"><div><span class="simnow-dot" :class="`simnow-dot--${data.observer?.status}`" /><strong>{{ observer }}</strong><span>{{ data.account?.alias }}</span><span>{{ data.account?.environment }}</span><span v-if="data.account?.scope_product">本次范围 {{ data.account.scope_product }}</span></div><span>柜台核验截至 {{ monitorTime(data.readback_at) }} <span v-if="data.trading_day">· 交易日 {{ data.trading_day }}</span></span></div>
      <p v-if="data.readback_status !== 'verified' || data.observer?.status !== 'running'" class="simnow-notice" role="status">{{ data.readback_status === 'pending' ? '账户或成交仍有待核事项，持仓及预算完整性尚未确认。' : '正在展示上次完整核验的记录，不代表柜台当前实时状态。' }}</p>
      <div class="simnow-metrics">
        <article><span>账户权益</span><strong>{{ monitorMoney(data.metrics.equity) }}</strong><small>元 · 原生账户</small></article>
        <article><span>可用资金</span><strong>{{ monitorMoney(data.metrics.available) }}</strong><small>元 · 截至核验时点</small></article>
        <article><span>已核验保证金占用</span><strong>{{ monitorPercent(data.metrics.margin_ratio) }} <em>/ 70%</em></strong><small>{{ monitorMoney(data.metrics.occupied_margin) }} / {{ monitorMoney(data.metrics.margin_limit) }} 元<br />柜台占用 {{ monitorMoney(data.metrics.used_margin) }} · 冻结 {{ monitorMoney(data.metrics.frozen_margin) }}</small></article>
        <article><span>本地未释放预留</span><strong>{{ monitorMoney(data.metrics.local_reserved_margin) }}</strong><small>另预留费用 {{ monitorMoney(data.metrics.local_reserved_fee) }} 元{{ data.readback_status === 'pending' ? ' · 抵扣待核' : '' }}</small></article>
        <article><span>柜台当日手续费</span><strong>{{ monitorMoney(data.metrics.daily_fee) }}</strong><small>已归属成交费用 {{ monitorMoney(data.metrics.attributed_fee) }} 元</small></article>
        <article><span>区间净收益</span><strong :class="data.metrics.net_profit !== null && Number(data.metrics.net_profit) < 0 ? 'simnow-down' : data.metrics.net_profit !== null && Number(data.metrics.net_profit) > 0 ? 'simnow-up' : ''">{{ monitorMoney(data.metrics.net_profit) }}</strong><small>{{ data.performance_status === 'CASHFLOW_CONTINUITY_REQUIRED' ? '跨日现金流连续性待核' : `现金流已调整 · ${monitorPercent(data.metrics.return_ratio)}` }}</small></article>
      </div>
      <section class="simnow-curve"><header><div><h2>账户走势</h2><span>近7天 · 仅原生留存点</span></div><div class="simnow-switch"><button type="button" :aria-pressed="curveField === 'equity'" @click="curveField = 'equity'">权益</button><button type="button" :aria-pressed="curveField === 'net_profit'" @click="curveField = 'net_profit'">区间净收益</button></div></header>
        <div v-if="geometry.dots.length" class="simnow-plot"><svg viewBox="0 0 1000 205" role="img" :aria-label="curveField === 'equity' ? '原生账户权益走势' : '可核验区间净收益走势'"><line x1="70" x2="970" y1="25" y2="25" /><line x1="70" x2="970" y1="165" y2="165" /><text x="0" y="29">{{ monitorMoney(geometry.max) }}</text><text x="0" y="169">{{ monitorMoney(geometry.min) }}</text><path v-for="(path, i) in geometry.segments" :key="i" :d="path" /><circle v-for="point in geometry.dots" :key="point.at" :cx="point.x" :cy="point.y" r="3"><title>{{ monitorTime(point.at) }} · {{ point.value }} 元</title></circle><text x="70" y="198">{{ monitorTime(data.curve[0]?.at) }}</text><text x="970" y="198" text-anchor="end">{{ monitorTime(data.curve.at(-1)?.at) }}</text></svg></div>
        <div v-else class="simnow-empty">{{ curveField === 'net_profit' && data.performance_status === 'CASHFLOW_CONTINUITY_REQUIRED' ? '跨日现金流尚未完整核验，净收益不补零或拼接。' : '等待可核验的账户走势记录。' }}</div>
      </section>
      <section class="simnow-records"><header class="simnow-records-heading"><nav aria-label="模拟交易内容"><button type="button" :aria-pressed="section === 'positions'" @click="section = 'positions'">持仓 <span>{{ data.positions.length }}</span></button><button type="button" :aria-pressed="section === 'records'" @click="section = 'records'">执行记录</button><button type="button" :aria-pressed="section === 'issues'" @click="section = 'issues'">待核事项 <span>{{ data.issue_count ?? '—' }}</span></button></nav><span>只读 · 不触发交易</span></header>
        <template v-if="section === 'positions'"><div class="simnow-table-wrap" v-if="data.positions.length"><table class="simnow-table simnow-positions"><thead><tr><th>品种 / 合约</th><th>方向</th><th>实际手数</th><th>今 / 昨</th><th>持仓损益</th><th>核验状态</th></tr></thead><tbody><tr v-for="position in data.positions" :key="position.id"><td><strong>{{ position.product }}</strong><small>{{ position.contract }}</small></td><td :class="position.side === 'LONG' ? 'simnow-up' : 'simnow-down'">{{ position.side === 'LONG' ? '多' : position.side === 'SHORT' ? '空' : '未知' }}</td><td>{{ position.quantity }}</td><td>{{ position.today ?? '—' }} / {{ position.yesterday ?? '—' }}</td><td>{{ monitorMoney(position.position_profit) }}</td><td><span class="simnow-badge" :class="{ 'simnow-badge--warning': position.status !== 'matched' }">{{ position.status === 'matched' ? '已核对' : '待核' }}</span></td></tr></tbody></table></div><p v-else class="simnow-empty">{{ data.position_projection_complete ? `截至 ${monitorTime(data.readback_at)}，柜台持仓为空。` : '持仓完整性尚未确认，不能据无记录判断空仓。' }}</p></template>
        <template v-else-if="section === 'records'">
          <div class="simnow-record-toolbar"><div class="simnow-record-kinds"><button v-for="category in categories" :key="category.value" type="button" :aria-pressed="query.kind === category.value" @click="query.kind = category.value">{{ category.label }}</button></div><div><button type="button" :aria-expanded="filtersOpen" @click="filtersOpen = !filtersOpen">筛选</button><button type="button" @click="reset">重置</button></div></div>
          <div v-if="filtersOpen" class="simnow-filters"><label>品种<select v-model="query.product"><option value="">全部品种</option><option v-for="product in props.options" :key="product.symbol" :value="product.symbol.toUpperCase()">{{ product.name }} {{ product.symbol.toUpperCase() }}</option></select></label><label>开始记录日期<input v-model="query.startDay" type="date" /></label><label>结束记录日期<input v-model="query.endDay" type="date" /></label><label>状态<select v-model="query.status"><option value="">全部状态</option><option value="REJECTED">拒绝</option><option value="FILLED">成交回报</option><option value="RECORDED">成交入账</option><option value="WORKING">已受理</option><option value="CANCEL_PENDING">撤单待核</option><option value="CANCELLED">已撤单</option><option value="UNKNOWN">结果未知</option><option value="LOCAL_ABORTED">本地未发送</option></select></label></div>
          <p v-if="!validRange" class="simnow-notice simnow-notice--warning" role="alert">请选择有效记录日期范围，最多相隔93天。日期按北京时间，不推算交易日。</p>
          <p v-if="monitor.newRecords.value" class="simnow-notice" role="status">有新的执行记录，当前列表与选择已保留。<button type="button" @click="monitor.reloadRecords()">刷新列表</button></p>
          <p v-if="monitor.recordsError.value" class="simnow-notice simnow-notice--warning" role="alert">{{ monitor.recordsError.value }}</p>
          <p v-if="monitor.recordsLoading.value" class="simnow-small-note">正在读取记录{{ monitor.page.value ? '，保留上次结果' : '' }}…</p>
          <div v-if="monitor.page.value?.items.length" class="simnow-table-wrap"><table class="simnow-table"><thead><tr><th>记录时间</th><th>类型</th><th>品种 / 合约</th><th>处理结果</th><th>价格 / 费用</th><th /></tr></thead><tbody><tr v-for="record in monitor.page.value.items" :key="record.id" @click="open(record.id)"><td>{{ monitorTime(record.at) }}<small v-if="record.facts.trading_day">交易日 {{ record.facts.trading_day }}</small></td><td>{{ kindLabel(record.kind) }}</td><td><strong>{{ record.product || '—' }}</strong><small>{{ record.contract || '—' }}</small></td><td><span class="simnow-badge" :class="{ 'simnow-badge--warning': ['REJECTED', 'UNKNOWN', 'PENDING', 'CONFLICT', 'CANCEL_PENDING'].includes(record.status) }">{{ record.label }}</span></td><td>{{ monitorMoney(record.facts.price) }}<small v-if="record.kind === 'fill'">费用 {{ monitorMoney(record.facts.fee) }}</small></td><td><button type="button" class="simnow-link" :aria-label="`查看执行链 ${record.product} ${record.label}`" @click.stop="open(record.id)">查看执行链</button></td></tr></tbody></table></div>
          <p v-else-if="!monitor.recordsLoading.value" class="simnow-empty">当前筛选下没有可展示的执行记录。</p>
          <footer class="simnow-record-footer"><span>已显示 {{ monitor.page.value?.items.length ?? 0 }} 条{{ monitor.page.value ? ` · 本次可读取 ${monitor.page.value.available_count} 条` : '' }} <span v-if="monitor.page.value?.coverage === 'partial'">· 覆盖不完整，请缩小范围</span></span><button v-if="monitor.page.value?.next_cursor" type="button" :disabled="monitor.loadingMore.value" @click="monitor.loadMore()">{{ monitor.loadingMore.value ? '读取中…' : '加载更多' }}</button></footer>
        </template>
        <div v-else class="simnow-issues"><p v-if="!data.issues.length" class="simnow-empty">当前已读取范围内没有待核事项。</p><article v-for="issue in data.issues" :key="issue.id"><span class="simnow-badge simnow-badge--warning">待核</span><div><strong>{{ issue.product ? `${issue.product} · ` : '' }}{{ issue.label }}</strong><p>{{ issue.contract }} · {{ monitorTime(issue.at) }}</p></div><button v-if="issue.link" type="button" class="simnow-link" @click="open(issue.link)">查看关联</button></article></div>
      </section>
      <p class="simnow-footnote">数据来自本地留存的柜台快照与执行账本。原始Live缺口和待核事实不会因历史补齐而消失；模拟账户表现与策略参考收益独立。</p>
    </template>
    <Teleport to="body"><dialog v-if="monitor.selectedId.value" ref="dialog" class="simnow-dialog market-dashboard-page" aria-labelledby="simnow-detail-title" @cancel.prevent="close" @click="event => { if (event.target === dialog) close() }"><header><div><span>火天大有 · 60分钟</span><h2 id="simnow-detail-title">执行链</h2></div><button type="button" aria-label="关闭执行链" @click="close">关闭 ×</button></header><p v-if="monitor.detailLoading.value" class="simnow-small-note">正在核对关联记录…</p><p v-if="monitor.detailError.value" class="simnow-notice simnow-notice--warning" role="alert">{{ monitor.detailError.value }}<button type="button" @click="monitor.openDetail(monitor.selectedId.value!)">重试</button></p><template v-if="monitor.detail.value"><p class="simnow-detail-subtitle">{{ monitor.detail.value.selected.product }} {{ monitor.detail.value.selected.contract }} · {{ monitor.detail.value.selected.label }}</p><ol class="simnow-chain"><li v-for="record in monitor.detail.value.chain" :key="record.id"><div class="simnow-chain-title"><strong>{{ kindLabel(record.kind) }}</strong><span class="simnow-badge">{{ record.label }}</span><time>{{ monitorTime(record.at) }}</time></div><p>{{ record.product }} {{ record.contract }}</p><dl><template v-for="(value, key) in record.facts" :key="key"><template v-if="factLabels[key]"><dt>{{ factLabels[key] }}</dt><dd>{{ factValue(key, value) }}</dd></template></template></dl><details><summary>来源与核验</summary><dl><dt>记录身份</dt><dd>{{ record.id }}</dd><template v-for="(value, key) in record.facts" :key="key"><template v-if="!factLabels[key] || key === 'reason'"><dt>{{ key }}</dt><dd>{{ value ?? '—' }}</dd></template></template></dl></details></li></ol></template></dialog></Teleport>
  </section>
</template>

