.simnow-metrics { display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:0;margin:18px 0;border:1px solid var(--gy-home-border);border-radius:8px;overflow:hidden; }
.simnow-metrics article { display:flex;flex-direction:column;gap:10px;min-width:0;padding:16px;border-right:1px solid var(--gy-home-border); }.simnow-metrics article:last-child {border-right:0;}.simnow-metrics span {font-size:12px;color:var(--gy-home-muted);}.simnow-metrics strong {font-size:22px;font-weight:650;white-space:nowrap;}.simnow-metrics em {font-size:12px;color:#98a2b3;font-style:normal;font-weight:400;}.simnow-metrics small {font-size:11px;color:var(--gy-home-muted);line-height:1.5;}
.simnow-up { color:var(--gy-home-up,#ff403a); }.simnow-down { color:var(--gy-home-down,#22b95d); }
.simnow-curve { border:1px solid var(--gy-home-border);border-radius:8px;padding:16px;margin-bottom:20px; }.simnow-curve header {display:flex;align-items:center;justify-content:space-between;gap:10px;}.simnow-curve header>div:first-child {display:flex;align-items:center;gap:16px;}.simnow-curve header span {font-size:12px;color:var(--gy-home-muted);}.simnow-curve h2 {font-size:15px;}.simnow-curve h2::before {display:none;}.simnow-switch {display:flex;gap:4px;}.simnow-switch button {font-size:12px;padding:4px 12px;min-height:30px;border-color:transparent;background:#f5f6f8;}.simnow-switch button[aria-pressed=true] {background:var(--gy-home-hover);color:var(--gy-home-accent);}
.simnow-plot { margin-top:12px; }.simnow-plot svg {width:100%;height:205px;overflow:visible;}.simnow-plot line {stroke:#eff0f3;stroke-dasharray:4 4;}.simnow-plot text {fill:#8a919d;font-size:11px;}.simnow-plot path {stroke:var(--gy-home-accent);stroke-width:2;fill:none;}.simnow-plot circle {fill:var(--gy-home-accent);stroke:#fff;stroke-width:1;}
